1|import { describe, expect, test } from 'vitest';
2|import { DOMAIN_REGEX } from '../../regex.ts';
3|import type { StringIssue } from '../../schemas/index.ts';
4|import { expectActionIssue, expectNoActionIssue } from '../../vitest/index.ts';
5|import { domain, type DomainAction, type DomainIssue } from './domain.ts';
6|
7|describe('domain', () => {
8|  describe('should return action object', () => {
9|    const baseAction: Omit<DomainAction<string, never>, 'message'> = {
10|      kind: 'validation',
11|      type: 'domain',
12|      reference: domain,
13|      expects: null,
14|      requirement: DOMAIN_REGEX,
15|      async: false,
16|      '~run': expect.any(Function),
17|    };
18|
19|    test('with undefined message', () => {
20|      const action: DomainAction<string, undefined> = {
21|        ...baseAction,
22|        message: undefined,
23|      };
24|      expect(domain()).toStrictEqual(action);
25|      expect(domain(undefined)).toStrictEqual(action);
26|    });
27|
28|    test('with string message', () => {
29|      expect(domain('message')).toStrictEqual({
30|        ...baseAction,
31|        message: 'message',
32|      } satisfies DomainAction<string, string>);
33|    });
34|
35|    test('with function message', () => {
36|      const message = () => 'message';
37|      expect(domain(message)).toStrictEqual({
38|        ...baseAction,
39|        message,
40|      } satisfies DomainAction<string, typeof message>);
41|    });
42|  });
43|
44|  describe('should return dataset without issues', () => {
45|    const action = domain();
46|
47|    // General tests
48|
49|    test('for untyped inputs', () => {
50|      const issues: [StringIssue] = [
51|        {
52|          kind: 'schema',
53|          type: 'string',
54|          input: null,
55|          expected: 'string',
56|          received: 'null',
57|          message: 'message',
58|        },
59|      ];
60|      expect(
61|        action['~run']({ typed: false, value: null, issues }, {})
62|      ).toStrictEqual({
63|        typed: false,
64|        value: null,
65|        issues,
66|      });
67|    });
68|
69|    test('for common domains', () => {
70|      expectNoActionIssue(action, [
71|        'example.com',
72|        'EXAMPLE.COM',
73|        'sub.example.com',
74|        'sub.sub2.example.co.uk',
75|      ]);
76|    });
77|  });
78|
79|  describe('should return dataset with issues', () => {
80|    const action = domain('message');
81|    const baseIssue: Omit<DomainIssue<string>, 'input' | 'received'> = {
82|      kind: 'validation',
83|      type: 'domain',
84|      expected: null,
85|      message: 'message',
86|      requirement: DOMAIN_REGEX,
87|    };
88|
89|    test('too long label (max 63 chars)', () => {
90|      expectActionIssue(action, baseIssue, ['a'.repeat(64) + '.com']);
91|    });
92|
93|    test('for empty or whitespace strings', () => {
94|      expectActionIssue(action, baseIssue, ['', ' ', '\n', '\t']);
95|    });
96|
97|    test('for missing TLD or single label', () => {
98|      expectActionIssue(action, baseIssue, [
99|        'localhost',
100|        'intranet',
101|        'example',
102|      ]);
103|    });
104|
105|    test('for invalid label starts/ends', () => {
106|      expectActionIssue(action, baseIssue, [
107|        '-example.com',
108|        'example-.com',
109|        '.example.com',
110|        'example..com',
111|        'example.com.',
112|        'example.c',
113|      ]);
114|    });
115|
116|    test('for invalid characters and formats', () => {
117|      expectActionIssue(action, baseIssue, [
118|        'exa mple.com',
119|        'example!.com',
120|        'exa*mple.com',
121|        'ex_amp.le.com',
122|        '*.example.com',
123|        'http://example.com',
124|      ]);
125|    });
126|  });
127|});

